values ('an','Elaboração de Book de Vendas','visualizacao',true,$$Elaboração de book de vendas com diagramação de informações comerciais aprovadas, plantas e imagens licenciadas, destinado à apresentação do empreendimento, sem elaboração automática de projetos ou renders extras.$$,'["Layout e diagramação de páginas contratadas","Organização de textos, plantas e imagens aprovados","PDF de apresentação"]'::jsonb,'["Projetos técnicos e renders adicionais","Garantia comercial de vendas ou valorização","Fornecimento de fontes editáveis e impressão não contratados"]'::jsonb,'["Conteúdo comercial verificado","Plantas e imagens autorizadas","Marca, formatos e número de páginas"]'::jsonb,null,'["PDF"]'::jsonb,true,$$Conforme escopo, insumos, marcos de entrega e prazo aprovados por atividade.$$,ARRAY['1.1','1.2','5.5','10.2','10.5','16.2']::text[],1,true,now(),(select version from public.contract_master_versions where active=true order by version desc limit 1))
