values ('ao','Emissão e Regularização de ART','documentacao',true,$$Providências administrativas relativas a ART de atividade técnica efetivamente assumida por profissional habilitado, incluindo registro, complementação, substituição e baixa quando cabíveis. A ART obrigatória do projeto não depende de contratação opcional.$$,'["Conferência de atividades e documentos","Cadastramento da ART legalmente cabível","Via do registro após pagamento da taxa"]'::jsonb,'["ART de execução sem contratação de execução","ART por atividade de terceiros não assumida","Taxa CREA não discriminada"]'::jsonb,'["Objeto, profissional e atribuições","Dados de contrato e local","Tipo de ART e custeio"]'::jsonb,null,'["PDF"]'::jsonb,true,$$Conforme escopo, insumos, marcos de entrega e prazo aprovados por atividade.$$,ARRAY['1.1','1.2','5.5','10.2','10.5','16.2']::text[],1,true,now(),(select version from public.contract_master_versions where active=true order by version desc limit 1))
