values('am','bronze',true,$$Projeto Hidráulico — nível BRONZE. Projeto predial de abastecimento e distribuição de água fria e, se selecionado, água quente, reservação, pressurização e pontos de consumo; não inclui automaticamente esgoto. Nível: execução essencial com produtos técnicos mínimos selecionados no orçamento. Entregas, abrangência, preços, prazos, visitas e revisões exigem definição individual no orçamento e Anexo I. ART de execução não está incluída em projeto; ART legalmente exigível para serviço técnico é obrigatória com custeio previamente definido.$$,$$A CONTRATADA prestará Projeto Hidráulico, nível BRONZE, exclusivamente nos limites, quantidades e etapas do Anexo I. Objeto: Projeto predial de abastecimento e distribuição de água fria e, se selecionado, água quente, reservação, pressurização e pontos de consumo; não inclui automaticamente esgoto. Entregáveis possíveis mediante contratação: plantas hidráulicas; ramais, reservatórios e prumadas; dimensionamento e esquemas; detalhes contratados. Exclusões do serviço: esgoto sanitário e drenagem não contratados; execução e ART de execução de obra; aprovação concessionária não contratada. execução essencial com produtos técnicos mínimos selecionados no orçamento. A contratação não afasta registro de ART legalmente exigível nem transfere responsabilidade de execução de obra.$$,$$ATIVIDADE: Projeto Hidráulico • NÍVEL BRONZE. OBJETO: Projeto predial de abastecimento e distribuição de água fria e, se selecionado, água quente, reservação, pressurização e pontos de consumo; não inclui automaticamente esgoto. ENTREGÁVEIS A ASSINALAR E QUANTIFICAR: plantas hidráulicas; ramais, reservatórios e prumadas; dimensionamento e esquemas; detalhes contratados. PARÂMETROS OBRIGATÓRIOS: água fria/quente; sistemas especiais; reservação; pontos e pavimentos; quantidade de pranchas. EXCLUSÕES ESPECÍFICAS: esgoto sanitário e drenagem não contratados; execução e ART de execução de obra; aprovação concessionária não contratada. NÍVEL: execução essencial com produtos técnicos mínimos selecionados no orçamento. [QUANTIDADES, PRANCHAS, FORMATOS, VISITAS, REVISÕES, PRAZOS, VALORES E CUSTEIO DE ART A DEFINIR]. Nenhum campo pendente pode ser presumido incluído ou publicado como texto definitivo.$$,'["Plantas de pontos e tubulações hidráulicas","Reservação e esquemas contratados","Dimensionamentos e especificações de água"]'::jsonb,'["Esgoto sanitário e drenagem pluvial não contratados","Execução e ART de execução","Concessionária e testes não contratados"]'::jsonb,'["delimitação do objeto e das unidades/áreas","quantidades e entregáveis","prazos, revisões e visitas","valor e custeio de taxas e ART quando cabível","aceite"]'::jsonb,2,null,'essencial','["PDF"]'::jsonb,false,'pending',(select version from public.service_catalog where code='am'),(select version from public.service_level_catalog where code='bronze'),1,true)
