insert into public.service_catalog_versions(service_code,version,snapshot,contract_master_version,created_by)
select code,version,to_jsonb(s),last_contract_master_version,null from public.service_catalog s where code in ('f','g','q','am','an','ao') on conflict(service_code,version) do nothing;
insert into public.service_level_scope_versions(service_code,level_code,version,snapshot,created_by)
select service_code,level_code,version,to_jsonb(s),null from public.service_level_scope_catalog s where service_code in ('f','g','q','am','an','ao') on conflict(service_code,level_code,version) do nothing;
COMMIT;
